using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Media.Entities;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Media.RegisterMedia;public sealed class RegisterMediaCommandHandler(IMediaReferenceRepository repo,IContentAuditService audit,IUnitOfWork uow):ICommandHandler<RegisterMediaCommand,Result<Guid>>{public async Task<Result<Guid>> HandleAsync(RegisterMediaCommand c,CancellationToken ct=default){if(await repo.ExistsByStorageFileIdAsync(c.StorageFileId,ct))return Result.Failure<Guid>(ContentErrors.StorageFileAlreadyRegistered);var x=MediaReference.Create(c.StorageFileId,c.FileName,c.ContentType,c.AltText,c.Caption,c.MetadataJson,c.ActorUserId);await repo.AddAsync(x,ct);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.MediaCreated,ContentAuditActions.Created,ContentAuditEntityTypes.MediaReference,x.Id,c.ActorUserId,After:ContentAuditSnapshots.From(x),Payload:new{x.StorageFileId,x.FileName}),ct);await uow.SaveChangesAsync(ct);return Result.Success(x.Id);}}
